  reserva: { tone: "casual brasileira, jovem e de boa aceitacao", tags: ["casual", "jovem", "presente"] },
  "reserva mini": { tone: "infantil casual, atual e com boa aceitacao", tags: ["infantil", "presente", "casual"] },
