function safeJsonParse(value, fallback) {
  try {
    const parsed = JSON.parse(String(value || ""));
    return parsed ?? fallback;
  } catch (error) {
    return fallback;
  }
}

function normalizeAllowedStores(value, fallbackStoreId = "") {
  const parsed = Array.isArray(value) ? value : safeJsonParse(value, []);
  const normalized = parsed
    .map((item) => normalizeStoreKey(item || ""))
    .filter(Boolean);
  if (normalized.length) {
    return Array.from(new Set(normalized));
  }
  const fallback = normalizeStoreKey(fallbackStoreId || "");
  return fallback ? [fallback] : [];
}

function normalizePermissionSet(value, role = "seller") {
  const parsed = value && typeof value === "object" && !Array.isArray(value)
    ? value
    : safeJsonParse(value, {});
  const merged = {
    ...buildDefaultPermissions(role),
    ...(parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {})
  };
  return Object.entries(merged).reduce((acc, [key, rawValue]) => {
    if (typeof rawValue === "string") {
      const normalized = rawValue.trim().toLowerCase();
      acc[key] = normalized === "true" || normalized === "1" || normalized === "yes";
      return acc;
    }
    if (typeof rawValue === "number") {
      acc[key] = rawValue > 0;
      return acc;
    }
    acc[key] = Boolean(rawValue);
    return acc;
  }, {});
}

function getStoreLabelFromUser(user = {}) {
  const normalizedStoreId = normalizeStoreKey(user.active_store_id || user.activeStoreId || user.active_store || user.store_id || user.storeId || user.store || "");
  const canonicalLabel = formatStoreLabel(normalizedStoreId);
  if (canonicalLabel && canonicalLabel !== "Loja" && canonicalLabel !== normalizedStoreId) {
    return canonicalLabel;
  }
  const explicitLabel = String(user.store_label || "").trim();
  const explicitStoreId = normalizeStoreKey(explicitLabel);
  const explicitCanonicalLabel = formatStoreLabel(explicitStoreId);
  if (explicitStoreId && explicitCanonicalLabel && explicitCanonicalLabel !== "Loja" && explicitCanonicalLabel !== explicitStoreId) {
    return explicitCanonicalLabel;
  }
  const fallbackLabel = {
    vila_masc: "Vila",
    vila_fem: "Vila",
    vila_fem_infant: "Vila",
    botanico: "Botânico",
    sul: "Sul"
  }[normalizedStoreId];
  return fallbackLabel || explicitLabel || String(user.store || "").trim();
}

function getStoreIdFromUser(user = {}) {
  return normalizeStoreKey(user.store_id || user.storeId || user.store || "");
}

function enrichUserRecord(user = {}) {
  if (!user) {
    return null;
  }
  const roleKey = normalizeSystemRole(user.role || user.role_key || "");
  const primaryStoreId = getStoreIdFromUser(user);
  const allowedStores = normalizeAllowedStores(user.allowed_stores_json || user.allowed_stores || [], primaryStoreId);
  const permissions = normalizePermissionSet(user.permissions_json || user.permissions || {}, roleKey);
  const hasAllStores = Boolean(permissions.can_view_all_stores) || roleKey === "admin";
  const hasFixedOperationalStore = ["seller", "cashier"].includes(roleKey);
  const effectiveAllowedStores = hasAllStores
    ? Array.from(new Set([...allowedStores, "vila", "botanico", "sul"].filter(Boolean)))
    : hasFixedOperationalStore
      ? (primaryStoreId ? [primaryStoreId] : [])
      : allowedStores;
  const activeStoreCandidate = normalizeStoreKey(user.active_store_id || user.activeStoreId || user.active_store || "");
  const activeStoreId = hasFixedOperationalStore && primaryStoreId
    ? primaryStoreId
    : activeStoreCandidate && (hasAllStores || effectiveAllowedStores.includes(activeStoreCandidate))
    ? activeStoreCandidate
    : (primaryStoreId || effectiveAllowedStores[0] || "");
  const activeStoreLabel = formatStoreLabel(activeStoreId);
  return {
    ...user,
    role_key: roleKey,
    primary_store_id: primaryStoreId,
    active_store_id: activeStoreId,
    store_id: activeStoreId,
    store_label: activeStoreLabel && activeStoreLabel !== "Loja" ? activeStoreLabel : getStoreLabelFromUser({ ...user, active_store_id: activeStoreId }),
    allowed_stores: effectiveAllowedStores,
    permissions
  };
}

function serializeAuthUser(user = {}) {
  const enriched = enrichUserRecord(user);
  if (!enriched) {
    return null;
  }
  const allowedStores = (enriched.allowed_stores || []).length
    ? enriched.allowed_stores
    : (enriched.permissions?.can_view_all_stores
      ? ["vila", "botanico", "sul"]
      : []);
  return {
    id: enriched.id,
    name: enriched.name || enriched.username || enriched.email || "Usuário AEROSTORE",
    email: enriched.email || "",
    username: enriched.username || "",
    phone: enriched.phone || "",
    role: enriched.role_key,
    legacyRole: enriched.role || "",
    status: enriched.status || "",
    store_id: enriched.store_id || null,
    active_store_id: enriched.active_store_id || enriched.store_id || null,
    primary_store_id: enriched.primary_store_id || enriched.store_id || null,
    store_label: enriched.store_label || "",
    allowed_stores: allowedStores,
    permissions: enriched.permissions || {},
    sellerId: enriched.seller_id || null,
    last_access_at: enriched.last_access_at || "",
    must_change_password: Boolean(Number(enriched.must_change_password || 0))
  };
}

function parseCookieHeader(cookieHeader = "") {
  return String(cookieHeader || "")
    .split(";")
    .map((item) => item.trim())
    .filter(Boolean)
    .reduce((acc, chunk) => {
      const separatorIndex = chunk.indexOf("=");
      if (separatorIndex <= 0) {
        return acc;
      }
      const key = chunk.slice(0, separatorIndex).trim();
      const value = chunk.slice(separatorIndex + 1).trim();
      acc[key] = decodeURIComponent(value);
      return acc;
    }, {});
}

function getSessionTokenFromRequest(req) {
  const cookies = parseCookieHeader(req.headers.cookie || "");
  const cookieToken = String(cookies[AUTH_COOKIE_NAME] || "").trim();
  if (cookieToken) {
    return cookieToken;
  }
  const authHeader = String(req.headers.authorization || "");
  if (authHeader.startsWith("Bearer ")) {
    return authHeader.slice(7).trim();
  }
  return "";
}

function getAuthCookieOptions() {
  const isProduction = String(process.env.NODE_ENV || "").trim().toLowerCase() === "production";
  return {
    httpOnly: true,
    secure: isProduction,
    sameSite: "Lax",
    path: "/",
    maxAge: AUTH_SESSION_MAX_AGE_MS
  };
}

function serializeCookie(name, value, options = {}) {
  const parts = [`${name}=${encodeURIComponent(String(value || ""))}`];
  if (options.maxAge !== undefined) {
    parts.push(`Max-Age=${Math.max(0, Math.floor(Number(options.maxAge || 0) / 1000))}`);
  }
  if (options.httpOnly) {
    parts.push("HttpOnly");
  }
  if (options.secure) {
    parts.push("Secure");
  }
  if (options.sameSite) {
    parts.push(`SameSite=${options.sameSite}`);
  }
  parts.push(`Path=${options.path || "/"}`);
  return parts.join("; ");
}

function setAuthSessionCookie(res, token) {
  res.setHeader("Set-Cookie", serializeCookie(AUTH_COOKIE_NAME, token, getAuthCookieOptions()));
}

function clearAuthSessionCookie(res) {
  res.setHeader("Set-Cookie", serializeCookie(AUTH_COOKIE_NAME, "", {
    ...getAuthCookieOptions(),
    maxAge: 0
  }));
}

async function getUserByToken(token) {
  if (!token) {
    return null;
  }

  const row = await get(
    `SELECT u.*, s.active_store_id AS active_store_id
     FROM users u
     INNER JOIN user_sessions s ON s.user_id = u.id
     WHERE s.token = ?
       AND s.expires_at > datetime('now')
       AND u.status = 'ativo'
     LIMIT 1`,
    [token]
  );
  return enrichUserRecord(row);
}

async function getUserByCredentials({ email = "", username = "", password = "" } = {}) {
  const normalizedEmail = String(email || "").trim().toLowerCase();
  const normalizedUsername = String(username || "").trim().toLowerCase();
  if ((!normalizedEmail && !normalizedUsername) || !password) {
    return null;
  }
  const clauses = [];
  const params = [];
  if (normalizedEmail) {
    clauses.push("lower(email) = ?");
    params.push(normalizedEmail);
  }
  if (normalizedUsername) {
    clauses.push("lower(username) = ?");
    params.push(normalizedUsername);
  }
  if (!clauses.length) {
    return null;
  }
  const user = await get(
    `SELECT *
     FROM users
     WHERE status = 'ativo'
       AND (${clauses.join(" OR ")})
     ORDER BY id ASC
     LIMIT 1`,
    params
  );
  if (!user || user.password_hash !== hashPassword(password)) {
    return null;
  }
  return enrichUserRecord(user);
}

function userHasPermission(user = {}, permission = "") {
  const key = String(permission || "").trim();
  if (!key) {
    return true;
  }
  const enriched = enrichUserRecord(user);
  return Boolean(enriched?.permissions?.[key]);
}

function userCanAccessStore(user = {}, storeId = "") {
  const normalizedStore = normalizeStoreKey(storeId || "");
  const enriched = enrichUserRecord(user);
  if (!enriched) {
    return false;
  }
  if (!normalizedStore) {
    return true;
  }
  if (userHasPermission(enriched, "can_view_all_stores")) {
    return true;
  }
  if (["seller", "cashier"].includes(enriched.role_key)) {
    return normalizedStore === normalizeStoreKey(enriched.primary_store_id || enriched.store_id || "");
  }
  return (enriched.allowed_stores || []).includes(normalizedStore);
}

function requirePermission(permission, message = "") {
  return (req, res, next) => {
    if (!userHasPermission(req.user, permission)) {
      recordAuditEvent({
        req,
        module: "security",
        action: "permission_denied",
        entityType: "endpoint",
        entityId: req.originalUrl || req.path || "",
        result: "blocked",
        message: message || "Acesso restrito para o seu perfil.",
        metadata: { permission }
      });
      return res.status(403).json({
        error: message || "Acesso restrito para o seu perfil.",
        permission
      });
    }
    next();
  };
}

function requireAnyPermission(permissionKeys = [], message = "") {
  const keys = Array.isArray(permissionKeys) ? permissionKeys.filter(Boolean) : [];
  return (req, res, next) => {
    if (!keys.length || keys.some((permission) => userHasPermission(req.user, permission))) {
      return next();
    }
    recordAuditEvent({
      req,
      module: "security",
      action: "permission_denied",
      entityType: "endpoint",
      entityId: req.originalUrl || req.path || "",
      result: "blocked",
      message: message || "Voce nao tem permissao para executar esta acao.",
      metadata: { permissions: keys }
    });
    return res.status(403).json({
      error: message || "Voce nao tem permissao para executar esta acao.",
      permissions: keys
    });
  };
}

function requireByHttpMethod(policy = {}, fallbackPermissions = []) {
  return (req, res, next) => {
    const method = String(req.method || "GET").toUpperCase();
    const permissions = policy[method] || fallbackPermissions || [];
    return requireAnyPermission(permissions)(req, res, next);
  };
}

function getCurrentStoreScope(req = {}) {
  const candidates = [
    req.query?.store,
    req.query?.storeId,
    req.body?.store,
    req.body?.storeId,
    req.body?.store_id,
    req.body?.loja,
    req.params?.storeId,
    req.params?.store_id
  ];
  const normalized = candidates
    .map((item) => normalizeStoreKey(item || ""))
    .find(Boolean);
  return normalized || getStoreIdFromUser(req.user || {});
}

function requireStoreAccess(options = {}) {
  const {
    resolver = (req) => getCurrentStoreScope(req),
    message = "Acesso restrito à sua loja."
  } = options || {};
  return (req, res, next) => {
    const scopeStore = normalizeStoreKey(typeof resolver === "function" ? resolver(req) : "");
    if (!scopeStore) {
      return next();
    }
    if (!userCanAccessStore(req.user, scopeStore)) {
      return res.status(403).json({ error: message, store_id: scopeStore });
    }
    next();
  };
}

const PDV_TINY_IMPORT_DESTINATION_STORES = new Set(["vila", "botanico", "sul"]);

function resolvePdvTinyImportDestinationStore(value = "") {
  const storeId = normalizeStoreKey(value || "");
  if (!storeId) {
    return {
      ok: false,
      status: 400,
      storeId: "",
      error: "Selecione a loja destino da importacao antes de gerar a previa."
    };
  }
  if (!PDV_TINY_IMPORT_DESTINATION_STORES.has(storeId)) {
    return {
      ok: false,
      status: 400,
      storeId,
      error: "Loja destino invalida para importacao Tiny. Use Vila, Botanico ou Sul."
    };
  }
  return {
    ok: true,
    status: 200,
    storeId,
    storeLabel: formatStoreLabel(storeId)
  };
}

async function assertPdvTinyImportStoreAccess(req, rawStoreValue = "") {
  const resolution = resolvePdvTinyImportDestinationStore(rawStoreValue);
  if (!resolution.ok) {
    await recordAuditEvent({
      req,
      module: "pdv_inventory",
      action: "tiny_import_store_rejected",
      entityType: "pdv_tiny_import",
      storeId: resolution.storeId || "",
      result: "blocked",
      message: resolution.error,
      includeBody: false,
      metadata: { requested_store: rawStoreValue || "" }
    });
    return resolution;
  }
  if (!userCanAccessStore(req.user || {}, resolution.storeId)) {
    await recordAuditEvent({
      req,
      module: "pdv_inventory",
      action: "tiny_import_store_denied",
      entityType: "pdv_tiny_import",
      storeId: resolution.storeId,
      storeName: resolution.storeLabel,
      result: "blocked",
      message: "Usuario sem permissao para importar nesta loja.",
      includeBody: false,
      metadata: { requested_store: rawStoreValue || "", allowed_stores: req.user?.allowed_stores || [] }
    });
    return {
      ok: false,
      status: 403,
      storeId: resolution.storeId,
      storeLabel: resolution.storeLabel,
      error: "Voce nao tem permissao para importar dados nesta loja."
    };
  }
  return resolution;
}

function resolveAuditMutationMeta(req = {}) {
  const pathName = getRequestPathname(req.originalUrl || req.path || "");
  const method = String(req.method || "").toUpperCase();
  const body = req.body || {};
  const params = req.params || {};
  const base = {
    module: "api",
    action: `${method.toLowerCase()}_mutation`,
    entity_type: "endpoint",
    entity_id: pathName
  };
  const rules = [
    [/\/api\/auth\/logout/, { module: "auth", action: "logout", entity_type: "session" }],
    [/\/api\/admin\/users/, { module: "users", action: "user_mutation", entity_type: "user", entity_id: params.id || body.id || "" }],
    [/\/api\/pdv\/sales\/finalize\//, { module: "pdv_sales", action: "sale_finalized", entity_type: "sale_session", entity_id: params.sessionId || "" }],
    [/\/api\/pdv\/sales\/cancel\//, { module: "pdv_sales", action: "sale_cancelled", entity_type: "sale", entity_id: params.saleId || "", sale_id: params.saleId || "" }],
    [/\/api\/pdv\/operational\/cart\/.*\/payment-plan/, { module: "pdv_sales", action: "payment_plan_changed", entity_type: "sale_session", entity_id: params.sessionId || "" }],
    [/\/api\/pdv\/operational\/cart\/.*\/discount$/, { module: "discounts", action: "general_discount_changed", entity_type: "sale_session", entity_id: params.sessionId || "" }],
    [/\/api\/pdv\/operational\/cart\/.*\/items\/.*\/discount/, { module: "discounts", action: "item_discount_changed", entity_type: "cart_item", entity_id: params.itemId || "" }],
    [/\/api\/pdv\/control\/authorizations\/validate/, { module: "authorizations", action: "authorization_token_validated", entity_type: "authorization" }],
    [/\/api\/pdv\/sales\/session\/.*\/apply-cashback/, { module: "cashback", action: "cashback_applied", entity_type: "sale_session", entity_id: params.sessionId || "" }],
    [/\/api\/pdv\/sales\/session\/.*\/apply-exchange-credit/, { module: "exchange_credit", action: "exchange_credit_applied", entity_type: "sale_session", entity_id: params.sessionId || "" }],
    [/\/api\/pdv\/sales\/exchanges/, { module: "exchange_credit", action: "exchange_credit_generated", entity_type: "exchange" }],
    [/\/api\/pdv\/inventory\/adjust/, {
      module: "inventory",
      action: "inventory_adjusted",
      entity_type: "product",
      product_id: body.product_id || body.productId || "",
      store_id: body.store_id || body.storeId || body.loja || ""
    }],
    [/\/api\/pdv\/inventory\/price-adjust/, {
      module: "inventory",
      action: "product_price_adjusted",
      entity_type: "product",
      product_id: body.product_id || body.productId || ""
    }],
    [/\/api\/pdv\/inventory\/transfer/, { module: "inventory", action: "inventory_transferred", entity_type: "product", product_id: body.product_id || body.productId || "" }],
    [/\/api\/pdv\/operational\/customers\/quick-register/, { module: "customers", action: "customer_created", entity_type: "customer" }],
    [/\/api\/products/, { module: "products", action: "product_mutation", entity_type: "product", product_id: params.id || params.productId || body.id || "" }],
    [/\/api\/customers/, { module: "customers", action: "customer_mutation", entity_type: "customer", customer_id: params.id || params.customerId || body.id || "" }]
  ];
  const match = rules.find(([pattern]) => pattern.test(pathName));
  return { ...base, ...(match ? match[1] : {}) };
}

function auditSensitiveMutationMiddleware(req, res, next) {
  const method = String(req.method || "").toUpperCase();
  if (!["POST", "PUT", "PATCH", "DELETE"].includes(method)) {
    return next();
  }
  const pathName = getRequestPathname(req.originalUrl || req.path || "");
  if (pathName.includes("/audit-logs")) {
    return next();
  }
  let responseBody = null;
  const originalJson = res.json.bind(res);
  res.json = (body) => {
    responseBody = body;
    return originalJson(body);
  };
  res.on("finish", () => {
    const statusCode = Number(res.statusCode || 0);
    const meta = resolveAuditMutationMeta(req);
    const result = statusCode === 403 ? "blocked" : statusCode >= 400 ? "failed" : "success";
    const includeBody = ![
      "/api/ia/responder",
      "/api/assistant",
      "/api/whatsapp",
      "/api/auth/change-password",
      "/api/auth/force-change-password",
      "/reset-password",
      "/api/admin/users"
    ].some((sensitivePath) => pathName.includes(sensitivePath));
    recordAuditEvent({
      req,
      ...meta,
      result,
      message: responseBody?.error || responseBody?.message || "",
      reason: req.body?.reason || "",
      amount: req.body?.amount || req.body?.value || null,
      after: statusCode < 400 ? responseBody : null,
      includeBody,
      metadata: { status_code: statusCode }
    });
  });
  next();
}

function getRoleProfile(role = "") {
  const normalized = normalizeSystemRole(role);
  return USER_ROLE_PROFILES.find((item) => item.key === normalized) || USER_ROLE_PROFILES.find((item) => item.key === "seller");
}

function getStoreOption(storeId = "") {
  const normalized = normalizeStoreKey(storeId || "");
  return STORE_ACCESS_OPTIONS.find((item) => item.id === normalized) || null;
}

function serializeAdminUser(row = {}) {
  const enriched = enrichUserRecord(row);
  if (!enriched) {
    return null;
  }
  const roleProfile = getRoleProfile(enriched.role_key);
  const storeOption = getStoreOption(enriched.store_id);
  return {
    id: enriched.id,
    name: enriched.name || enriched.username || enriched.email || "",
    email: enriched.email || "",
    username: enriched.username || "",
    phone: enriched.phone || "",
    role: enriched.role_key,
    role_label: roleProfile?.label || enriched.role_key,
    legacyRole: enriched.role || "",
    store_id: enriched.store_id || "",
    store_label: storeOption?.label || enriched.store_label || "",
    allowed_stores: enriched.allowed_stores || [],
    permissions: enriched.permissions || {},
    seller_id: enriched.seller_id || null,
    status: enriched.status || "ativo",
    must_change_password: Boolean(Number(enriched.must_change_password || 0)),
    created_at: enriched.created_at || "",
    updated_at: enriched.updated_at || "",
    last_access_at: enriched.last_access_at || ""
  };
}

function normalizeAdminUserPayload(body = {}, existing = null) {
  const role = normalizeSystemRole(body.role || body.role_key || existing?.role || "seller");
  const storeId = normalizeStoreKey(body.store_id || body.storeId || body.store || existing?.store_id || "vila") || "vila";
  const storeLabel = getStoreOption(storeId)?.label || String(body.store_label || body.store || existing?.store || "").trim() || storeId;
  const defaultPermissions = buildDefaultPermissions(role);
  const explicitPermissions = body.permissions && typeof body.permissions === "object" && !Array.isArray(body.permissions)
    ? body.permissions
    : {};
  const permissions = normalizePermissionSet({ ...defaultPermissions, ...explicitPermissions }, role);
  const allowedStoresInput = Array.isArray(body.allowed_stores)
    ? body.allowed_stores
    : Array.isArray(body.allowedStores)
      ? body.allowedStores
      : existing?.allowed_stores_json || [];
  const allowedStores = normalizeAllowedStores(allowedStoresInput, storeId);
  return {
    name: String(body.name ?? existing?.name ?? "").trim(),
    email: String(body.email ?? existing?.email ?? "").trim().toLowerCase(),
    username: String(body.username ?? existing?.username ?? "").trim().toLowerCase(),
    phone: String(body.phone ?? existing?.phone ?? "").trim(),
    role,
    store: storeLabel,
    store_id: storeId,
    allowed_stores_json: JSON.stringify(allowedStores),
    permissions_json: JSON.stringify(permissions),
    status: String(body.status ?? existing?.status ?? "ativo").trim().toLowerCase() === "inativo" ? "inativo" : "ativo",
    seller_id: body.seller_id || body.sellerId || existing?.seller_id || null
  };
}

function buildUsersAdminMeta() {
  return {
    profiles: USER_ROLE_PROFILES.map((profile) => ({
      ...profile,
      default_permissions: buildDefaultPermissions(profile.key)
    })),
    permission_catalog: USER_PERMISSION_CATALOG,
    store_options: STORE_ACCESS_OPTIONS
  };
}

async function listAdminUsers(req, res) {
  const q = String(req.query.q || "").trim().toLowerCase();
  const role = String(req.query.role || "").trim().toLowerCase();
  const status = String(req.query.status || "").trim().toLowerCase();
  const clauses = [];
  const params = [];
  if (q) {
    clauses.push("(lower(email) LIKE ? OR lower(username) LIKE ? OR lower(name) LIKE ? OR lower(store) LIKE ?)");
    params.push(`%${q}%`, `%${q}%`, `%${q}%`, `%${q}%`);
  }
  if (role) {
    clauses.push("lower(role) = ?");
    params.push(role);
  }
  if (status) {
    clauses.push("lower(status) = ?");
    params.push(status);
  }
  const rows = await all(
    `SELECT id, email, role, store, seller_id, status, created_at, updated_at,
            name, username, phone, store_id, allowed_stores_json, permissions_json, last_access_at, must_change_password
     FROM users
     ${clauses.length ? `WHERE ${clauses.join(" AND ")}` : ""}
     ORDER BY CASE WHEN status = 'ativo' THEN 0 ELSE 1 END, name COLLATE NOCASE ASC, email COLLATE NOCASE ASC`,
    params
  );
  res.json({
    users: rows.map(serializeAdminUser).filter(Boolean),
    meta: buildUsersAdminMeta()
  });
}

async function createAdminUser(req, res) {
  const payload = normalizeAdminUserPayload(req.body || {});
  const password = String(req.body?.password || "").trim();
  if (!payload.email || !payload.name) {
    return res.status(400).json({ error: "Informe nome e e-mail do usuario." });
  }
  const passwordValidation = validatePasswordStrength(password);
  if (!passwordValidation.ok) {
    return res.status(400).json({ error: passwordValidation.error });
  }
  const existing = await get("SELECT id FROM users WHERE lower(email) = ? LIMIT 1", [payload.email]);
  if (existing?.id) {
    return res.status(409).json({ error: "Ja existe usuario com este e-mail." });
  }
  const mustChangePassword = req.body?.mustChangePassword === false ? 0 : 1;
  const result = await run(
    `INSERT INTO users
      (email, password_hash, role, store, seller_id, status, created_at, updated_at,
       name, username, phone, store_id, allowed_stores_json, permissions_json, must_change_password)
     VALUES (?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'), ?, ?, ?, ?, ?, ?, ?)`,
    [
      payload.email,
      hashPassword(password),
      payload.role,
      payload.store,
      payload.seller_id,
      payload.status,
      payload.name,
      payload.username,
      payload.phone,
      payload.store_id,
      payload.allowed_stores_json,
      payload.permissions_json,
      mustChangePassword
    ]
  );
  const user = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [result?.lastID]);
  res.status(201).json({ user: serializeAdminUser(user), meta: buildUsersAdminMeta() });
}

async function updateAdminUser(req, res) {
  const userId = Number(req.params.id || 0);
  const existing = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  const payload = normalizeAdminUserPayload(req.body || {}, existing);
  if (!payload.email || !payload.name) {
    return res.status(400).json({ error: "Informe nome e e-mail do usuario." });
  }
  const nextPermissions = safeJsonParse(payload.permissions_json, {});
  if (Number(req.user?.id || 0) === userId && (!nextPermissions.can_manage_users || payload.status !== "ativo")) {
    return res.status(400).json({ error: "Voce nao pode remover seu proprio acesso administrativo." });
  }
  const duplicate = await get("SELECT id FROM users WHERE lower(email) = ? AND id <> ? LIMIT 1", [payload.email, userId]);
  if (duplicate?.id) {
    return res.status(409).json({ error: "Ja existe outro usuario com este e-mail." });
  }
  await run(
    `UPDATE users SET
       email = ?,
       role = ?,
       store = ?,
       seller_id = ?,
       status = ?,
       name = ?,
       username = ?,
       phone = ?,
       store_id = ?,
       allowed_stores_json = ?,
       permissions_json = ?,
       updated_at = datetime('now')
     WHERE id = ?`,
    [
      payload.email,
      payload.role,
      payload.store,
      payload.seller_id,
      payload.status,
      payload.name,
      payload.username,
      payload.phone,
      payload.store_id,
      payload.allowed_stores_json,
      payload.permissions_json,
      userId
    ]
  );
  const nextPassword = String(req.body?.password || "").trim();
  if (nextPassword) {
    const passwordValidation = validatePasswordStrength(nextPassword);
    if (!passwordValidation.ok) {
      return res.status(400).json({ error: passwordValidation.error });
    }
    await run(
      "UPDATE users SET password_hash = ?, must_change_password = 1, updated_at = datetime('now') WHERE id = ?",
      [hashPassword(nextPassword), userId]
    );
  }
  const user = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  res.json({ user: serializeAdminUser(user), meta: buildUsersAdminMeta() });
}

async function resetAdminUserPassword(req, res) {
  const userId = Number(req.params.id || 0);
  const password = String(req.body?.newPassword || req.body?.password || "").trim();
  const passwordValidation = validatePasswordStrength(password);
  if (!passwordValidation.ok) {
    return res.status(400).json({ error: passwordValidation.error });
  }
  const existing = await get("SELECT id FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  const mustChangePassword = req.body?.mustChangePassword === false ? 0 : 1;
  await run(
    "UPDATE users SET password_hash = ?, must_change_password = ?, updated_at = datetime('now') WHERE id = ?",
    [hashPassword(password), mustChangePassword, userId]
  );
  await recordAuditEvent({
    req,
    module: "auth",
    action: "user_password_reset_by_admin",
    entityType: "user",
    entityId: String(userId),
    result: "success",
    message: "Senha redefinida por administrador",
    includeBody: false,
    metadata: { must_change_password: Boolean(mustChangePassword) }
  });
  res.json({ success: true });
}

async function setAdminUserStatus(req, res) {
  const userId = Number(req.params.id || 0);
  const status = String(req.body?.status || "").trim().toLowerCase() === "inativo" ? "inativo" : "ativo";
  if (Number(req.user?.id || 0) === userId && status === "inativo") {
    return res.status(400).json({ error: "Voce nao pode desativar seu proprio usuario." });
  }
  const existing = await get("SELECT id FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  await run("UPDATE users SET status = ?, updated_at = datetime('now') WHERE id = ?", [status, userId]);
  const user = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  res.json({ user: serializeAdminUser(user), meta: buildUsersAdminMeta() });
}

async function deleteAdminUser(req, res) {
  const userId = Number(req.params.id || 0);
  if (Number(req.user?.id || 0) === userId) {
    return res.status(400).json({ error: "Voce nao pode excluir seu proprio usuario." });
  }
  const existing = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  const marker = `${existing.email || ""} ${existing.name || ""} ${existing.username || ""}`.toLowerCase();
  const canDeleteSafely = marker.includes("teste") || marker.includes("test") || String(existing.status || "").toLowerCase() === "inativo";
  if (!canDeleteSafely) {
    return res.status(409).json({
      error: "Usuario com possivel historico operacional. Desative em vez de excluir para preservar vendas antigas."
    });
  }
  await run("DELETE FROM user_sessions WHERE user_id = ?", [userId]);
  await run("DELETE FROM users WHERE id = ?", [userId]);
  res.json({ success: true });
}

function listAccessibleStoreSettings(user = {}) {
  const rows = listStoreSettings();
  if (isAdmin(user) || userHasPermission(user, "can_view_all_stores")) {
    return rows;
  }
  return rows.filter((row) => userCanAccessStore(user, row.store_id || ""));
}

function getStoreSettingsSummary(row = {}) {
  return {
    store_id: row.store_id || "",
    display_name: row.display_name || formatStoreLabel(row.store_id || ""),
    internal_name: row.internal_name || "",
    status: row.status || "active",
    type: row.type || "",
    contact: {
      phone: row.contact?.phone || "",
      whatsapp: row.contact?.whatsapp || "",
      email: row.contact?.email || "",
      manager_name: row.contact?.manager_name || "",
      opening_hours: row.contact?.opening_hours || ""
    },
    metadata: {
      updated_at: row.metadata?.updated_at || "",
      updated_by: row.metadata?.updated_by || ""
    }
  };
}

function sanitizeStoreSettingsText(value = "") {
  return String(value || "").replace(/\s+/g, " ").trim();
}

function sanitizeStoreSettingsEmail(value = "") {
  return sanitizeStoreSettingsText(value).toLowerCase();
}

function sanitizeStoreSettingsCnpj(value = "") {
  return String(value || "").replace(/\D+/g, "").slice(0, 14);
}

function isValidStoreSettingsCnpj(value = "") {
  const digits = sanitizeStoreSettingsCnpj(value);
  return !digits || digits.length === 14;
}

function sanitizeStoreSettingsZip(value = "") {
  return String(value || "").replace(/\D+/g, "").slice(0, 8);
}

function sanitizeStoreSettingsState(value = "") {
  return sanitizeStoreSettingsText(value).toUpperCase().slice(0, 2);
}

function isValidStoreSettingsEmail(value = "") {
  const normalized = sanitizeStoreSettingsEmail(value);
  return !normalized || /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalized);
}

function isValidStoreSettingsPhone(value = "") {
  const digits = String(value || "").replace(/\D+/g, "");
  return !digits || digits.length >= 10;
}

function validateStoreSettingsPayload(record = {}) {
  if (!sanitizeStoreSettingsText(record.store_id || "")) {
    return "store_id é obrigatório.";
  }
  if (!sanitizeStoreSettingsText(record.display_name || "")) {
    return "display_name é obrigatório.";
  }
  if (!STORE_STATUSES.includes(String(record.status || "").trim().toLowerCase())) {
    return "status da loja inválido.";
  }
  if (!STORE_TYPES.includes(String(record.type || "").trim().toLowerCase())) {
    return "type da loja inválido.";
  }
  if (!isValidStoreSettingsCnpj(record.company?.cnpj || "")) {
    return "CNPJ inválido.";
  }
  if (record.address?.state && sanitizeStoreSettingsState(record.address.state).length !== 2) {
    return "UF deve ter 2 letras.";
  }
  if (!isValidStoreSettingsEmail(record.contact?.email || "")) {
    return "E-mail da loja inválido.";
  }
  if (!isValidStoreSettingsPhone(record.contact?.phone || "") || !isValidStoreSettingsPhone(record.contact?.whatsapp || "")) {
    return "Telefone ou WhatsApp da loja inválido.";
  }
  return "";
}

function buildNormalizedStoreSettingsPayload(payload = {}, current = {}) {
  const storeId = normalizeStoreKey(payload.store_id || current.store_id || "");
  const displayName = sanitizeStoreSettingsText(payload.display_name || current.display_name || formatStoreLabel(storeId));
  return {
    store_id: storeId,
    legacy_aliases: normalizeStoreSettingsStringArray(payload.legacy_aliases ?? current.legacy_aliases ?? []),
    display_name: displayName,
    internal_name: sanitizeStoreSettingsText(payload.internal_name || current.internal_name || `AEROSTORE ${displayName}`),
    status: STORE_STATUSES.includes(String(payload.status || current.status || "").trim().toLowerCase())
      ? String(payload.status || current.status).trim().toLowerCase()
      : "active",
    type: STORE_TYPES.includes(String(payload.type || current.type || "").trim().toLowerCase())
      ? String(payload.type || current.type).trim().toLowerCase()
      : "physical_store",
    company: {
      legal_name: sanitizeStoreSettingsText(payload.company?.legal_name ?? current.company?.legal_name ?? ""),
      trade_name: sanitizeStoreSettingsText(payload.company?.trade_name ?? current.company?.trade_name ?? displayName),
      cnpj: sanitizeStoreSettingsCnpj(payload.company?.cnpj ?? current.company?.cnpj ?? ""),
      state_registration: sanitizeStoreSettingsText(payload.company?.state_registration ?? current.company?.state_registration ?? ""),
      municipal_registration: sanitizeStoreSettingsText(payload.company?.municipal_registration ?? current.company?.municipal_registration ?? ""),
      tax_regime_label: sanitizeStoreSettingsText(payload.company?.tax_regime_label ?? current.company?.tax_regime_label ?? "")
    },
    address: {
      zip: sanitizeStoreSettingsZip(payload.address?.zip ?? current.address?.zip ?? ""),
      street: sanitizeStoreSettingsText(payload.address?.street ?? current.address?.street ?? ""),
      number: sanitizeStoreSettingsText(payload.address?.number ?? current.address?.number ?? ""),
      complement: sanitizeStoreSettingsText(payload.address?.complement ?? current.address?.complement ?? ""),
      district: sanitizeStoreSettingsText(payload.address?.district ?? current.address?.district ?? ""),
      city: sanitizeStoreSettingsText(payload.address?.city ?? current.address?.city ?? ""),
      state: sanitizeStoreSettingsState(payload.address?.state ?? current.address?.state ?? ""),
      country: sanitizeStoreSettingsText(payload.address?.country ?? current.address?.country ?? "Brasil")
    },
    contact: {
      phone: sanitizeStoreSettingsText(payload.contact?.phone ?? current.contact?.phone ?? ""),
      whatsapp: sanitizeStoreSettingsText(payload.contact?.whatsapp ?? current.contact?.whatsapp ?? ""),
      email: sanitizeStoreSettingsEmail(payload.contact?.email ?? current.contact?.email ?? ""),
      manager_name: sanitizeStoreSettingsText(payload.contact?.manager_name ?? current.contact?.manager_name ?? ""),
      opening_hours: sanitizeStoreSettingsText(payload.contact?.opening_hours ?? current.contact?.opening_hours ?? "")
    },
    terminal: {
      default_register_id: sanitizeStoreSettingsText(payload.terminal?.default_register_id ?? current.terminal?.default_register_id ?? ""),
      default_terminal_label: sanitizeStoreSettingsText(payload.terminal?.default_terminal_label ?? current.terminal?.default_terminal_label ?? ""),
      default_printer_label: sanitizeStoreSettingsText(payload.terminal?.default_printer_label ?? current.terminal?.default_printer_label ?? ""),
      receipt_footer: sanitizeStoreSettingsText(payload.terminal?.receipt_footer ?? current.terminal?.receipt_footer ?? ""),
      sale_prefix: sanitizeStoreSettingsText(payload.terminal?.sale_prefix ?? current.terminal?.sale_prefix ?? "")
    },
    inventory: {
      primary_deposit_id: sanitizeStoreSettingsText(payload.inventory?.primary_deposit_id ?? current.inventory?.primary_deposit_id ?? ""),
      linked_deposit_ids: normalizeStoreSettingsStringArray(payload.inventory?.linked_deposit_ids ?? current.inventory?.linked_deposit_ids ?? []),
      allows_shared_stock: normalizeStoreSettingsBoolean(payload.inventory?.allows_shared_stock, current.inventory?.allows_shared_stock ?? true),
      allows_transfer_request: normalizeStoreSettingsBoolean(payload.inventory?.allows_transfer_request, current.inventory?.allows_transfer_request ?? true),
      requires_cross_state_transfer_review: normalizeStoreSettingsBoolean(payload.inventory?.requires_cross_state_transfer_review, current.inventory?.requires_cross_state_transfer_review ?? false)
    },
    policies: {
      cashback_generate_enabled: normalizeStoreSettingsBoolean(payload.policies?.cashback_generate_enabled, current.policies?.cashback_generate_enabled ?? true),
      cashback_redeem_enabled: normalizeStoreSettingsBoolean(payload.policies?.cashback_redeem_enabled, current.policies?.cashback_redeem_enabled ?? true),
      payment_link_enabled: normalizeStoreSettingsBoolean(payload.policies?.payment_link_enabled, current.policies?.payment_link_enabled ?? true),
      gift_card_enabled: normalizeStoreSettingsBoolean(payload.policies?.gift_card_enabled, current.policies?.gift_card_enabled ?? true),
      exchange_enabled: normalizeStoreSettingsBoolean(payload.policies?.exchange_enabled, current.policies?.exchange_enabled ?? true),
      auto_discount_enabled: normalizeStoreSettingsBoolean(payload.policies?.auto_discount_enabled, current.policies?.auto_discount_enabled ?? true),
      local_discount_limit_percent: payload.policies?.local_discount_limit_percent === null || payload.policies?.local_discount_limit_percent === ""
        ? null
        : Number(payload.policies?.local_discount_limit_percent ?? current.policies?.local_discount_limit_percent ?? 0),
      pickup_enabled: normalizeStoreSettingsBoolean(payload.policies?.pickup_enabled, current.policies?.pickup_enabled ?? true),
      delivery_enabled: normalizeStoreSettingsBoolean(payload.policies?.delivery_enabled, current.policies?.delivery_enabled ?? false),
      delivery_policy_label: sanitizeStoreSettingsText(payload.policies?.delivery_policy_label ?? current.policies?.delivery_policy_label ?? ""),
      operational_notes: sanitizeStoreSettingsText(payload.policies?.operational_notes ?? current.policies?.operational_notes ?? "")
    },
    integrations: {
      whatsapp_instance_id: sanitizeStoreSettingsText(payload.integrations?.whatsapp_instance_id ?? current.integrations?.whatsapp_instance_id ?? ""),
      pagbank_account_label: sanitizeStoreSettingsText(payload.integrations?.pagbank_account_label ?? current.integrations?.pagbank_account_label ?? ""),
      tiny_store_id: sanitizeStoreSettingsText(payload.integrations?.tiny_store_id ?? current.integrations?.tiny_store_id ?? ""),
      tiny_deposit_id: sanitizeStoreSettingsText(payload.integrations?.tiny_deposit_id ?? current.integrations?.tiny_deposit_id ?? "")
    }
  };
}

function buildManagerEditableStoreSettingsPayload(payload = {}, current = {}) {
  const next = buildNormalizedStoreSettingsPayload(current, current);
  return {
    ...next,
    contact: {
      ...next.contact,
      phone: sanitizeStoreSettingsText(payload.contact?.phone ?? current.contact?.phone ?? ""),
      whatsapp: sanitizeStoreSettingsText(payload.contact?.whatsapp ?? current.contact?.whatsapp ?? ""),
      email: sanitizeStoreSettingsEmail(payload.contact?.email ?? current.contact?.email ?? ""),
      manager_name: sanitizeStoreSettingsText(payload.contact?.manager_name ?? current.contact?.manager_name ?? ""),
      opening_hours: sanitizeStoreSettingsText(payload.contact?.opening_hours ?? current.contact?.opening_hours ?? "")
    },
    policies: {
      ...next.policies,
      operational_notes: sanitizeStoreSettingsText(payload.policies?.operational_notes ?? current.policies?.operational_notes ?? "")
    }
  };
}

function finalizeStoreSettingsRecord(nextRecord = {}, current = {}, actor = "") {
  return {
    ...nextRecord,
    metadata: {
      ...(current.metadata || {}),
      created_at: current.metadata?.created_at || new Date().toISOString(),
      updated_at: new Date().toISOString(),
      updated_by: actor || getUserDisplayName({})
    }
  };
}

function escapeCsvValue(value) {
  return `"${String(value ?? "").replace(/"/g, '""')}"`;
}

function calculateCashbackValue(purchaseValue, percentage) {
  return Number((Number(purchaseValue || 0) * (Number(percentage || 0) / 100)).toFixed(2));
}

function getCashbackUsageLimit(purchaseValue, availableBalance) {
  return Number(Math.min(Number(availableBalance || 0), Number(purchaseValue || 0) * 0.5).toFixed(2));
}

function getConfiguredCashbackPercentage(settings) {
  const configured = Array.isArray(settings?.percentages)
    ? settings.percentages.map(Number).filter((value) => value > 0)
    : [];
  return configured[0] || 12;
}

function randomPin() {
  return String(Math.floor(1000 + Math.random() * 9000));
}

function hashCashbackPin(pin) {
  return crypto
    .createHash("sha256")
    .update(`${PIN_HASH_PEPPER}:${String(pin || "").trim()}`)
    .digest("hex");
}

function compareCashbackPin(pin, expectedHash) {
  if (!pin || !expectedHash) {
    return false;
  }
  return hashCashbackPin(pin) === String(expectedHash || "");
}

function normalizePinTokenStatus(status) {
  const value = String(status || "").trim().toLowerCase();
  const map = {
    pendente: "pending",
    pending: "pending",
    enviado: "sent",
    sent: "sent",
    validado: "validated",
    validated: "validated",
    expirado: "expired",
    expired: "expired",
    cancelado: "cancelled",
    cancelled: "cancelled",
    failed: "failed",
    bloqueado: "failed"
  };
  return map[value] || "pending";
}

function parsePercentages(value) {
  try {
    const parsed = JSON.parse(value || "[]");
    return Array.isArray(parsed)
      ? parsed.map((item) => Number(item)).filter((item) => item > 0)
      : [5, 10, 15, 20];
  } catch (error) {
    return [5, 10, 15, 20];
  }
}

function mapCashbackStatus(status) {
  const normalized = String(status || "").trim().toLowerCase();
  const map = {
    ativo: "disponivel",
    disponivel: "disponivel",
    a_receber: "a_receber",
    "a receber": "a_receber",
    usado: "usado",
    expirado: "vencido",
    vencido: "vencido",
    cancelado: "cancelado"
  };
  return map[normalized] || "disponivel";
}

function buildContactPayload(payload) {
  return {
    name: String(payload.name || "").trim(),
    phone: normalizePhone(payload.phone),
    document: normalizeDocumentValue(payload.document || payload.cpf || ""),
    email: normalizeEmailValue(payload.email || ""),
    birthDate: String(payload.birthDate || payload.birth_date || "").trim().slice(0, 10),
    zipcode: normalizeZipcodeValue(payload.zipcode || payload.cep || ""),
    city: normalizeCityValue(payload.city || payload.cidade || ""),
    state: normalizeStateValue(payload.state || payload.uf || ""),
    neighborhood: normalizeWhitespace(payload.neighborhood || payload.bairro || ""),
    topSize: normalizeWhitespace(payload.topSize || payload.top_size || "").toUpperCase(),
    bottomSize: normalizeWhitespace(payload.bottomSize || payload.bottom_size || ""),
    shoeSize: normalizeWhitespace(payload.shoeSize || payload.shoe_size || ""),
    gender: String(payload.gender || "").trim(),
    store: String(payload.store || "").trim(),
    sellerId: payload.sellerId ? Number(payload.sellerId) : null,
    sellerName: String(payload.sellerName || "").trim(),
    tags: "",
    cashback: 0,
    status: String(payload.status || "ativo").trim(),
    notes: String(payload.notes || payload.commercialNotes || "").trim()
  };
}

function getUserDisplayName(user) {
  return user?.name || user?.username || user?.email || "Sistema";
}

function isAdmin(user) {
  return normalizeSystemRole(user?.role_key || user?.role || "") === "admin";
}

function isManager(user) {
  return ["admin", "manager"].includes(normalizeSystemRole(user?.role_key || user?.role || ""));
}

function buildCashbackPreviewPayload({ contact, phone, name, gender, store, sellerName, purchaseValue, settings, availableCashback = 0 }) {
  const validFrom = getToday();
  const expiresAt = addDays(validFrom, settings.defaultValidityDays);
  const percentage = getConfiguredCashbackPercentage(settings);
  const cashbackUsed = getCashbackUsageLimit(purchaseValue, availableCashback);
  const amountPaid = Number((Number(purchaseValue || 0) - cashbackUsed).toFixed(2));
  const generatedValue = calculateCashbackValue(purchaseValue, percentage);
  return {
    contactId: contact?.id || null,
    customerName: contact?.name || String(name || "").trim(),
    customerPhone: normalizePhone(contact?.phone || phone || ""),
    customerGender: contact?.gender || String(gender || "").trim(),
    store: String(store || contact?.store || "").trim(),
    sellerName: String(sellerName || contact?.seller_name || "").trim(),
    percentage,
    purchaseValue: Number(purchaseValue || 0),
    availableCashback: Number(availableCashback || 0),
    cashbackUsed,
    amountPaid,
    generatedValue,
    validFrom,
    expiresAt,
    usageLimitText: "Use até 50% do valor da compra.",
    termsLink: TERMS_LINK
  };
}

function validateContact(contact) {
  if (!contact.name) {
    return "O nome do contato e obrigatorio.";
  }
  if (!contact.phone && !contact.document) {
    return "Telefone ou CPF do contato e obrigatorio.";
  }
  if (contact.document && contact.document.length !== 11) {
    return "CPF do contato invalido.";
  }
  return null;
}

function normalizeBooleanFlag(value, fallback = false) {
  if (value === undefined || value === null || value === "") {
    return Boolean(fallback);
  }
  if (typeof value === "boolean") {
    return value;
  }
  if (typeof value === "number") {
    return value > 0;
  }
  const normalized = String(value || "").trim().toLowerCase();
  return ["1", "true", "sim", "yes", "on", "ativo"].includes(normalized);
}

function normalizeCustomerStatus(status = "") {
  const normalized = String(status || "").trim().toLowerCase();
  if (["ativo", "inativo", "oculto", "deleted", "excluido"].includes(normalized)) {
    return normalized === "excluido" ? "deleted" : normalized;
  }
  return "ativo";
}

function normalizeCustomerConfidence(value = "") {
  const normalized = normalizeLookup(value || "");
  if (["alta", "media", "baixa"].includes(normalized)) {
    return normalized;
  }
  return "media";
}

function normalizeCustomerSource(value = "") {
  const normalized = normalizeLookup(value || "");
  const allowed = ["manual", "tiny", "importacao", "importação", "whatsapp", "campanha", "aerointel", "outro"];
  if (!allowed.includes(normalized)) {
    return "manual";
  }
  return normalized === "importação" ? "importacao" : normalized;
}

function normalizeBrazilMobile(value = "") {
  const digits = sanitizePhone(value);
  if (!digits) {
    return "";
  }
  let normalized = digits;
  if (normalized.startsWith("0")) {
    normalized = normalized.replace(/^0+/, "");
  }
  if (normalized.startsWith("55") && normalized.length >= 12) {
    normalized = normalized.slice(0, 13);
  } else if ((normalized.length === 10 || normalized.length === 11) && !normalized.startsWith("55")) {
    normalized = `55${normalized}`;
  }
  return /^55\d{10,11}$/.test(normalized) ? normalized : "";
}

function buildCustomerQualityFlags(payload = {}, { allowMissingName = true } = {}) {
  const flags = new Set();
  if (!payload.name && allowMissingName) {
    flags.add("needs_name_review");
  }
  if (!payload.mobile && !payload.document) {
    flags.add("missing_identity");
  }
  if (!payload.mobile) {
    flags.add("missing_mobile");
  }
  if (payload.mobile && !payload.mobile_normalized) {
    flags.add("invalid_mobile");
  }
  if (!payload.document) {
    flags.add("missing_document");
  }
  return Array.from(flags);
}

function parseStoredJsonArray(value) {
  const parsed = safeJsonParse(value, []);
  return Array.isArray(parsed) ? parsed : [];
}

function parseStoredJsonObject(value) {
  const parsed = safeJsonParse(value, {});
  return parsed && typeof parsed === "object" && !Array.isArray(parsed) ? parsed : {};
}

