const PUBLIC_API_PATHS = new Set([
  "/api/health",
  "/api/login",
  "/api/auth/login",
  "/api/instance/info"
]);

function getRequestPathname(requestPath = "") {
  return String(requestPath || "").split("?")[0].trim();
}

function isPublicApiPath(requestPath = "") {
  return PUBLIC_API_PATHS.has(getRequestPathname(requestPath));
}

const LOG_SENSITIVE_KEYS = new Set([
  "authorization",
  "cookie",
  "password",
  "senha",
  "pin",
  "token",
  "secret",
  "password_hash",
  "access_token",
  "refresh_token"
]);

function maskPhoneForLog(value = "") {
  const digits = String(value || "").replace(/\D/g, "");
  if (!digits) return "";
  return digits.length <= 4 ? `***${digits}` : `***${digits.slice(-4)}`;
}

function sanitizeLogPayload(value, depth = 0) {
  if (depth > 4) {
    return "[TRUNCATED]";
  }
  if (Array.isArray(value)) {
    return value.slice(0, 20).map((item) => sanitizeLogPayload(item, depth + 1));
  }
  if (value && typeof value === "object") {
    return Object.entries(value).reduce((acc, [key, item]) => {
      const normalizedKey = normalizeText(key).toLowerCase();
      if (LOG_SENSITIVE_KEYS.has(normalizedKey) || normalizedKey.includes("token") || normalizedKey.includes("secret")) {
        acc[key] = "[REDACTED]";
      } else if (["phone", "telefone", "mobile", "whatsapp"].includes(normalizedKey)) {
        acc[key] = maskPhoneForLog(item);
      } else if (["message", "mensagem", "body", "text", "customer_message", "conversation"].includes(normalizedKey)) {
        acc[key] = normalizeText(item).slice(0, 80) ? "[REDACTED_TEXT]" : "";
      } else {
        acc[key] = sanitizeLogPayload(item, depth + 1);
      }
      return acc;
    }, {});
  }
  return value;
}

function safeCompareSecrets(received = "", expected = "") {
  const receivedText = normalizeText(received);
  const expectedText = normalizeText(expected);
  if (!receivedText || !expectedText) {
    return false;
  }
  const receivedBuffer = Buffer.from(receivedText);
  const expectedBuffer = Buffer.from(expectedText);
  return receivedBuffer.length === expectedBuffer.length && crypto.timingSafeEqual(receivedBuffer, expectedBuffer);
}

async function notifyCashbackCreditedSafe(cashback, req = null) {
  if (!cashback || !cashback.id) return null;
  try {
    const result = await getNotificationService().sendCashbackNotification(cashback, {
      dryRun: getNotificationDryRunDefault()
    });
    await recordAuditEvent({
      req: req || undefined,
      module: "notifications",
      action: "cashback_credit_notification",
      entityType: "cashback",
      entityId: String(cashback.id),
      customerId: String(cashback.contact_id || ""),
      amount: Number(cashback.generated_value || cashback.available_balance || 0),
      result: result.success ? "success" : "failed",
      message: result.dryRun
        ? "Notificacao de cashback registrada em dry-run."
        : "Notificacao de cashback processada.",
      metadata: {
        provider: result.provider,
        template: result.templateName,
        status: result.status,
        dry_run: Boolean(result.dryRun),
        phone: result.toMasked || ""
      }
    }).catch(() => {});
    return result;
  } catch (error) {
    await recordAuditEvent({
      req: req || undefined,
      module: "notifications",
      action: "cashback_credit_notification_failed",
      entityType: "cashback",
      entityId: String(cashback.id),
      result: "failed",
      message: "Falha ao processar notificacao WhatsApp Cloud.",
      metadata: { error: String(error.message || error).slice(0, 160) }
    }).catch(() => {});
    return { success: false, status: "failed", error: "notification_failed" };
  }
}

const PAGBANK_WEBHOOK_EVENT_CACHE_TTL_MS = 1000 * 60 * 60 * 6;
const pagBankWebhookEventCache = new Map();

function prunePagBankWebhookEventCache() {
  const now = Date.now();
  for (const [key, timestamp] of pagBankWebhookEventCache.entries()) {
    if (now - Number(timestamp || 0) > PAGBANK_WEBHOOK_EVENT_CACHE_TTL_MS) {
      pagBankWebhookEventCache.delete(key);
    }
  }
}

function getPagBankWebhookEventKey(req = {}, payload = {}, source = "") {
  const body = payload && typeof payload === "object" ? payload : {};
  const nested = body.data && typeof body.data === "object" ? body.data : {};
  const candidates = [
    req.headers?.["x-request-id"],
    req.headers?.["x-pagbank-event-id"],
    req.headers?.["x-pagseguro-notification-id"],
    body.event_id,
    body.eventId,
    body.notification_id,
    body.notificationCode,
    body.code,
    body.id,
    nested.id,
    nested.code
  ].map((item) => normalizeText(item)).filter(Boolean);
  if (candidates.length) {
    return `${source}:${candidates[0]}`;
  }
  const reference = [
    source,
    body.checkout_id || body.checkoutId || nested.checkout_id || nested.checkoutId || "",
    body.reference_id || body.referenceId || nested.reference_id || nested.referenceId || "",
    body.sale_id || nested.sale_id || "",
    body.status || nested.status || body.payment_status || nested.payment_status || ""
  ].map((item) => normalizeText(item)).join("|");
  return reference.replace(/\|/g, "") ? crypto.createHash("sha256").update(reference).digest("hex") : "";
}

async function recordPagBankWebhookAudit(req = {}, { source = "", result = "", message = "", eventKey = "", mapped = null } = {}) {
  try {
    await recordAuditEvent({
      req,
      module: "payments",
      action: "pagbank_webhook",
      entityType: "webhook",
      entityId: eventKey || source,
      saleId: mapped?.sale?.sale_id || mapped?.sale_id || "",
      result,
      message,
      includeBody: false,
      metadata: {
        provider: "pagbank",
        source,
        event_key: eventKey,
        matched: Boolean(mapped?.matched),
        payment_status: mapped?.payment_link?.payment_status || mapped?.payment_status || ""
      }
    });
  } catch (error) {
    console.error("[AUDIT] PagBank webhook audit failed", sanitizeLogPayload({ message: error.message || String(error) }));
  }
}

function validatePagBankWebhookRequest(req = {}) {
  const expectedSecret = normalizeText(process.env.PAGBANK_WEBHOOK_SECRET || "");
  if (!expectedSecret) {
    return {
      ok: false,
      status: 503,
      error: "Webhook PagBank sem segredo configurado no servidor."
    };
  }
  const receivedSecret = req.headers?.["x-aerostore-pagbank-webhook-secret"] || "";
  if (!safeCompareSecrets(receivedSecret, expectedSecret)) {
    return {
      ok: false,
      status: 403,
      error: "Webhook PagBank nao autorizado."
    };
  }
  return { ok: true };
}

async function handlePagBankWebhook(req, res, source = "generic") {
  const validation = validatePagBankWebhookRequest(req);
  const eventKey = getPagBankWebhookEventKey(req, req.body || {}, source);
  if (!validation.ok) {
    await recordPagBankWebhookAudit(req, {
      source,
      result: "blocked",
      message: validation.error,
      eventKey
    });
    console.warn("[PAGBANK WEBHOOK] blocked", sanitizeLogPayload({
      source,
      event_key: eventKey,
      status: validation.status,
      reason: validation.error,
      ip: req.ip || req.socket?.remoteAddress || ""
    }));
    return res.status(validation.status).json({ error: validation.error });
  }

  prunePagBankWebhookEventCache();
  if (eventKey && pagBankWebhookEventCache.has(eventKey)) {
    await recordPagBankWebhookAudit(req, {
      source,
      result: "success",
      message: "Webhook PagBank duplicado ignorado.",
      eventKey
    });
    return res.status(200).json({ received: true, duplicate: true });
  }

  try {
    const mapped = applyPagBankWebhookToSale(req.body || {}, { source });
    if (eventKey) {
      pagBankWebhookEventCache.set(eventKey, Date.now());
    }
    await recordPagBankWebhookAudit(req, {
      source,
      result: "success",
      message: "Webhook PagBank aceito.",
      eventKey,
      mapped
    });
    console.info("[PAGBANK WEBHOOK] accepted", sanitizeLogPayload({
      source,
      event_key: eventKey,
      matched: Boolean(mapped?.matched),
      sale_id: mapped?.sale?.sale_id || ""
    }));
    return res.status(200).json({ received: true, mapped });
  } catch (error) {
    await recordPagBankWebhookAudit(req, {
      source,
      result: "failed",
      message: error.message || "Falha ao processar webhook PagBank.",
      eventKey
    });
    console.error("[PAGBANK WEBHOOK] error", sanitizeLogPayload({
      source,
      event_key: eventKey,
      message: error.message || String(error)
    }));
    return res.status(200).json({ received: true });
  }
}

async function authMiddleware(req, res, next) {
  if (isPublicApiPath(req.originalUrl || req.path || "")) {
    return next();
  }
  const token = getSessionTokenFromRequest(req);

  const user = await getUserByToken(token);

  if (!user) {
    if (["POST", "PUT", "PATCH", "DELETE"].includes(String(req.method || "").toUpperCase())) {
      recordAuditEvent({
        req,
        module: "security",
        action: "unauthenticated_request",
        entityType: "endpoint",
        entityId: req.originalUrl || req.path || "",
        result: "blocked",
        message: "Sessao expirada ou usuario nao autenticado"
      });
    }
    console.warn('[AUTH] Token inválido ou expirado:', { path: req.originalUrl, hasToken: !!token });
    res.status(401).json({ error: "Sessão expirada ou usuário não autenticado", details: "Faça login novamente" });
    return;
  }

  req.user = user;
  next();
}

function requireManager(req, res, next) {
  if (!isManager(req.user) || !userHasPermission(req.user, "can_manage_store_settings")) {
    res.status(403).json({ error: "Acesso restrito a gerente ou admin." });
    return;
  }
  next();
}

function requireAdmin(req, res, next) {
  if (!isAdmin(req.user)) {
    res.status(403).json({ error: "Acesso restrito a admin." });
    return;
  }
  next();
}

async function findDuplicateContactByPhone(phone, exceptId = null) {
  const normalized = normalizePhone(phone);
  if (!normalized) {
    return null;
  }
  const phoneExpr = "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(phone, '+', ''), '(', ''), ')', ''), '-', ''), ' ', '')";
  const params = [normalized, normalized.slice(2)];
  let sql = `SELECT * FROM contacts WHERE (${phoneExpr} = ? OR ${phoneExpr} = ?)`;
  if (exceptId) {
    sql += " AND id <> ?";
    params.push(Number(exceptId));
  }
  sql += " ORDER BY id DESC LIMIT 1";
  return get(sql, params);
}

async function findDuplicateContact({ phone = "", document = "", email = "" } = {}, exceptId = null) {
  const normalizedPhone = normalizePhone(phone);
  const normalizedDocument = normalizeDocumentValue(document);
  const normalizedEmail = normalizeEmailValue(email);
  if (!normalizedPhone && !normalizedDocument && !normalizedEmail) {
    return null;
  }

  const clauses = [];
  const params = [];
  const phoneExpr = "REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(COALESCE(phone, ''), '+', ''), '(', ''), ')', ''), '-', ''), ' ', '')";
  if (normalizedPhone) {
    clauses.push(`(${phoneExpr} = ? OR ${phoneExpr} = ?)`);
    params.push(normalizedPhone, normalizedPhone.slice(2));
  }
  if (normalizedDocument) {
    clauses.push("REPLACE(REPLACE(REPLACE(COALESCE(document, ''), '.', ''), '-', ''), '/', '') = ?");
    params.push(normalizedDocument);
  }
  if (normalizedEmail) {
    clauses.push("LOWER(COALESCE(email, '')) = ?");
    params.push(normalizedEmail);
  }

  let sql = `SELECT * FROM contacts WHERE (${clauses.join(" OR ")})`;
  if (exceptId) {
    sql += " AND id <> ?";
    params.push(Number(exceptId));
  }
  sql += " ORDER BY id DESC LIMIT 1";
  return get(sql, params);
}

async function resolveSellerPayload(payload = {}, allowInactive = true) {
  const sellerId = payload.sellerId ? Number(payload.sellerId) : null;
  const fallbackName = String(payload.sellerName || payload.seller || "").trim();

  if (sellerId) {
    const seller = await getSellerById(sellerId);
    if (seller && (allowInactive || seller.status === "ativo")) {
      return {
        sellerId: seller.id,
        sellerName: seller.name,
        sellerStore: seller.store
      };
    }
  }

  return {
    sellerId: null,
    sellerName: fallbackName,
    sellerStore: ""
  };
}

async function incrementMetric(key, amount = 1) {
  await run("UPDATE metrics SET value = value + ? WHERE key = ?", [amount, key]);
}

async function ensureContactByPayload(payload) {
  if (payload.contactId) {
    const found = await get("SELECT * FROM contacts WHERE id = ?", [payload.contactId]);
    if (found) {
      return found;
    }
  }

  const phone = normalizePhone(payload.phone);
  if (phone) {
    const foundByPhone = await get("SELECT * FROM contacts WHERE phone = ?", [phone]);
    if (foundByPhone) {
      return foundByPhone;
    }
  }

  const seller = await resolveSellerPayload(payload, true);
  const contact = buildContactPayload({
    name: payload.name,
    phone,
    gender: payload.gender || "",
    store: payload.store || "",
    sellerId: seller.sellerId,
    sellerName: seller.sellerName,
    tags: "importado, cashback",
    cashback: 0,
    status: "ativo",
    notes: "Criado automaticamente pelo AEROSTORE Cashback"
  });

  const result = await run(
    `INSERT INTO contacts
    (name, phone, gender, store, seller_id, seller_name, tags, cashback, validity, status, notes, created_at, updated_at)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), datetime('now'))`,
    [
      contact.name,
      contact.phone,
      contact.gender,
      contact.store,
      contact.sellerId,
      contact.sellerName,
      contact.tags,
      contact.cashback,
      "",
      contact.status,
      contact.notes
    ]
  );

  return get("SELECT * FROM contacts WHERE id = ?", [result.lastID]);
}

async function createCashbackEvent({
  cashbackId,
  contactId,
  eventType,
  value,
  store,
  seller,
  eventDate,
  campaign,
  status,
  lostValue,
  expiredAt,
  lostAt,
  origin,
  ticket,
  nf,
  reason,
  pin,
  notes
}) {
  await run(
    `INSERT INTO cashback_events
    (cashback_id, contact_id, event_type, value, store, seller, event_date, campaign, status, lost_value, expired_at, lost_at, origin, ticket, nf, reason, pin, created_at, notes)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, datetime('now'), ?)`,
    [
      cashbackId || null,
      contactId,
      eventType,
      Number(value || 0),
      String(store || ""),
      String(seller || ""),
      String(eventDate || getToday()),
      String(campaign || ""),
      String(status || ""),
      Number(lostValue || 0),
      String(expiredAt || ""),
      String(lostAt || ""),
      String(origin || ""),
      String(ticket || ""),
      String(nf || ""),
      String(reason || ""),
      String(pin || ""),
      String(notes || "")
    ]
  );
}

async function syncContactCashback(contactId) {
  const totals = await get(
    `SELECT
      COALESCE(SUM(available_balance), 0) AS available_balance,
      MIN(CASE WHEN status = 'disponivel' AND available_balance > 0 AND expires_at <> '' THEN expires_at END) AS next_expiration
    FROM cashbacks
    WHERE contact_id = ?`,
    [contactId]
  );

  await run(
    `UPDATE contacts SET
    cashback = ?,
    validity = COALESCE(?, ''),
    updated_at = datetime('now')
    WHERE id = ?`,
    [Number(totals?.available_balance || 0), totals?.next_expiration || "", contactId]
  );
}

async function expireCashbacks() {
  const today = getToday();
  const rows = await all(
    `SELECT * FROM cashbacks
    WHERE status = 'disponivel' AND expires_at <> '' AND expires_at < ? AND available_balance > 0`,
    [today]
  );

  for (const cashback of rows) {
    const existingEvent = await get(
      `SELECT id FROM cashback_events
      WHERE cashback_id = ? AND event_type = 'cashback_vencido'
      ORDER BY id DESC LIMIT 1`,
      [cashback.id]
    );

    await run(
      `UPDATE cashbacks SET
      lost_value = lost_value + available_balance,
      available_balance = 0,
      status = 'vencido',
      updated_at = datetime('now')
      WHERE id = ?`,
      [cashback.id]
    );

    if (!existingEvent) {
      await createCashbackEvent({
        cashbackId: cashback.id,
        contactId: cashback.contact_id,
        eventType: "cashback_vencido",
        value: cashback.available_balance,
        store: cashback.store,
        seller: cashback.seller,
        notes: "Bônus vencido automaticamente."
      });
    }

    await syncContactCashback(cashback.contact_id);
  }
}

async function getCashbackById(id) {
  await expireCashbacks();
  return get("SELECT * FROM cashbacks WHERE id = ?", [id]);
}

async function getActiveCashbacksByContactId(contactId) {
  return all(
    `SELECT * FROM cashbacks
    WHERE contact_id = ? AND status = 'disponivel' AND available_balance > 0
    ORDER BY CASE WHEN expires_at = '' THEN 1 ELSE 0 END ASC, expires_at ASC, id ASC`,
    [contactId]
  );
}

async function getAvailableCashbackTotal(contactId) {
  if (!contactId) {
    return 0;
  }
  const row = await get(
    `SELECT COALESCE(SUM(available_balance), 0) AS total
    FROM cashbacks
    WHERE contact_id = ? AND status = 'disponivel' AND available_balance > 0`,
    [contactId]
  );
  return Number(row?.total || 0);
}

async function consumeCashbackPool(contactId, usedAmount, actorName) {
  let remaining = Number(usedAmount || 0);
  if (!contactId || remaining <= 0) {
    return;
  }

  const rows = await getActiveCashbacksByContactId(contactId);
  for (const cashback of rows) {
    if (remaining <= 0) {
      break;
    }
    const available = Number(cashback.available_balance || 0);
    const usedHere = Number(Math.min(available, remaining).toFixed(2));
    const lostHere = Number((available - usedHere).toFixed(2));
    await run(
      `UPDATE cashbacks SET
      used_value = used_value + ?,
      lost_value = lost_value + ?,
      available_balance = 0,
      status = 'usado',
      used_at = datetime('now'),
      updated_at = datetime('now')
      WHERE id = ?`,
      [usedHere, lostHere, cashback.id]
    );
    await createCashbackEvent({
      cashbackId: cashback.id,
      contactId: cashback.contact_id,
      eventType: "cashback_resgatado",
      value: usedHere,
      store: cashback.store,
      seller: actorName || cashback.seller,
      notes: "Bônus consumido no wizard de cashback."
    });
    remaining = Number((remaining - usedHere).toFixed(2));
  }
}

function applyVariables(template, campaign, contact) {
  const replacements = {
    "{{nome}}": contact.name || "",
    "{{telefone}}": contact.phone || "",
    "{{vendedor}}": contact.seller_name || campaign.seller || "",
    "{{loja}}": contact.store || campaign.store || "",
    "{{cashback}}": formatCurrencyNumber(contact.cashback || 0),
    "{{validade}}": formatDateBR(contact.validity || contact.expires_at || ""),
    "{{status}}": contact.status || "",
    "{{dias}}": String(contact.days_until_expiration ?? ""),
    "{{compra_minima}}": formatCurrencyNumber(contact.minimum_purchase || 0),
    "{{cashback_perdido}}": formatCurrencyNumber(contact.cashback_lost || 0),
    "{{event_date}}": formatDateBR(contact.event_date || ""),
    "{{lost_at}}": formatDateBR(contact.lost_at || ""),
    "{{expired_at}}": formatDateBR(contact.expired_at || ""),
    "{{data_perda}}": formatDateBR(contact.lost_at || contact.expired_at || contact.event_date || "")
  };

  return Object.entries(replacements).reduce(
    (message, [token, value]) => message.split(token).join(value),
    template
  );
}

function buildCashbackMessage(type, cashback) {
  const payload = {
    nome: cashback.customer_name,
    vendedor: cashback.seller || "AEROSTORE",
    cashback: formatCurrencyNumber(cashback.available_balance || cashback.generated_value),
    validade: formatDateBR(cashback.expires_at) || "a data informada",
    loja: cashback.store || "AEROSTORE",
    dataInicio: formatDateBR(cashback.valid_from || getToday()),
    dataFim: formatDateBR(cashback.expires_at) || "a data informada",
    linkTermos: TERMS_LINK
  };

  const templates = {
    gerado:
      "AEROSTORE:\n\n{{nome}}, você tem R$ {{cashback}} de bônus para sua próxima compra.\n\nVálido de {{dataInicio}} até {{dataFim}}\n\nUse até 50% do valor da compra.\n\nAo utilizar o bônus você concorda com:\n{{linkTermos}}",
    vencendo:
      "Oi {{nome}}, seu cashback de R$ {{cashback}} na AEROSTORE vence em breve. Quer aproveitar hoje?",
    reativado:
      "Oi {{nome}}, reativei seu cashback de R$ {{cashback}} na AEROSTORE. Ele esta valido até {{validade}}. Quer ver as novidades?",
    perdido:
      "Oi {{nome}}, vi que seu cashback venceu. Posso tentar uma condicao especial pra você voltar na AEROSTORE?"
  };

  const template = templates[type] || templates.gerado;
  return template
    .replace(/{{nome}}/g, payload.nome)
    .replace(/{{vendedor}}/g, payload.vendedor)
    .replace(/{{cashback}}/g, payload.cashback)
    .replace(/{{validade}}/g, payload.validade)
    .replace(/{{loja}}/g, payload.loja)
    .replace(/{{data_inicio}}/g, payload.dataInicio)
    .replace(/{{data_fim}}/g, payload.dataFim)
    .replace(/{{dataInicio}}/g, payload.dataInicio)
    .replace(/{{dataFim}}/g, payload.dataFim)
    .replace(/{{link_termos}}/g, payload.linkTermos)
    .replace(/{{linkTermos}}/g, payload.linkTermos);
}

