app.get("/api/runtime-version", authMiddleware, requireAnyPermission(["can_manage_global_settings", "can_manage_users"]), async (req, res) => {
  let tables = [];
  const isProduction = String(process.env.NODE_ENV || "").trim().toLowerCase() === "production";
  if (!isProduction) {
    try {
      tables = await all(
        `SELECT name
         FROM sqlite_master
         WHERE type = 'table'
           AND name IN ('ai_conversation_state', 'ai_product_categories', 'ai_product_genders', 'ai_product_colors', 'ai_product_sizes')
         ORDER BY name`
      );
    } catch (error) {
      tables = [];
    }
  }

  const payload = {
    version: RUNTIME_VERSION,
    bootTime: BOOT_TIME,
    nodeVersion: process.version,
    environment: String(process.env.NODE_ENV || "development")
  };
  if (!isProduction) {
    payload.database = path.basename(dbPath || "");
    payload.tables = tables.map((item) => item.name);
  }
  res.json(payload);
});

async function handleAuthLogin(req, res) {
  try {
    const usernameOrEmail = String(req.body.username || req.body.email || req.body.login || "").trim();
    const email = usernameOrEmail.includes("@") ? usernameOrEmail.toLowerCase() : "";
    const username = usernameOrEmail.includes("@") ? "" : usernameOrEmail.toLowerCase();
    const password = String(req.body.password || "");
    if ((!email && !username) || !password) {
      res.status(400).json({ error: "Informe usuário/e-mail e senha." });
      return;
    }

    const user = await getUserByCredentials({ email, username, password });
    if (!user) {
      res.status(401).json({ error: "Credenciais invalidas." });
      return;
    }

    const token = createSessionToken();
    const expiresAt = new Date(Date.now() + AUTH_SESSION_MAX_AGE_MS).toISOString();
    await run(
      "INSERT INTO user_sessions (user_id, token, expires_at, active_store_id, created_at) VALUES (?, ?, ?, ?, datetime('now'))",
      [user.id, token, expiresAt, normalizeStoreKey(user.store_id || user.primary_store_id || "")]
    );
    await run("UPDATE users SET last_access_at = datetime('now'), updated_at = datetime('now') WHERE id = ?", [user.id]);
    setAuthSessionCookie(res, token);
    recordAuditEvent({
      req: { ...req, user },
      module: "auth",
      action: "login",
      entityType: "session",
      entityId: String(user.id || ""),
      result: "success",
      message: "Login realizado"
    });

    res.json({
      success: true,
      session: COOKIE_SESSION_MARKER,
      must_change_password: Boolean(Number(user.must_change_password || 0)),
      user: serializeAuthUser(user)
    });
  } catch (error) {
    res.status(500).json({ error: "Falha ao realizar login." });
  }
}

