async function handleAuthActiveStore(req, res) {
  const requestedStoreId = normalizeStoreKey(req.body?.store_id || req.body?.storeId || req.body?.store || "");
  const storeOption = STORE_ACCESS_OPTIONS.find((item) => item.id === requestedStoreId);
  if (!requestedStoreId || !storeOption) {
    return res.status(400).json({ error: "Loja ativa invalida.", store_id: requestedStoreId || "" });
  }
  if (!userCanAccessStore(req.user || {}, requestedStoreId)) {
    await recordAuditEvent({
      req,
      module: "auth",
      action: "active_store_denied",
      entityType: "store",
      entityId: requestedStoreId,
      storeId: requestedStoreId,
      storeName: storeOption.label,
      result: "blocked",
      message: "Usuario sem permissao para trocar para esta loja.",
      metadata: { requested_store: requestedStoreId, allowed_stores: req.user?.allowed_stores || [] }
    });
    return res.status(403).json({ error: "Seu perfil nao tem permissao para operar esta loja.", store_id: requestedStoreId });
  }
  const token = getSessionTokenFromRequest(req);
  await run(
    "UPDATE user_sessions SET active_store_id = ? WHERE token = ?",
    [requestedStoreId, token]
  );
  const refreshedUser = await getUserByToken(token);
  await recordAuditEvent({
    req: { ...req, user: refreshedUser || req.user },
    module: "auth",
    action: "active_store_changed",
    entityType: "store",
    entityId: requestedStoreId,
    storeId: requestedStoreId,
    storeName: storeOption.label,
    result: "success",
    message: `Loja ativa alterada para ${storeOption.label}.`
  });
  res.json({
    success: true,
    store_id: requestedStoreId,
    store_label: storeOption.label,
    user: serializeAuthUser(refreshedUser || { ...req.user, active_store_id: requestedStoreId })
  });
}

async function handleAuthChangePassword(req, res) {
  const userId = Number(req.user?.id || 0);
  const currentPassword = String(req.body?.currentPassword || "");
  const newPassword = String(req.body?.newPassword || "");
  if (!userId) {
    return res.status(401).json({ error: "Sessao expirada. Faca login novamente." });
  }
  if (!currentPassword) {
    return res.status(400).json({ error: "Informe a senha atual." });
  }
  const passwordValidation = validatePasswordStrength(newPassword);
  if (!passwordValidation.ok) {
    return res.status(400).json({ error: passwordValidation.error });
  }
  const existing = await get("SELECT id, password_hash FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  const currentHash = hashPassword(currentPassword);
  const nextHash = hashPassword(newPassword);
  if (currentHash !== existing.password_hash) {
    return res.status(403).json({ error: "Senha atual invalida." });
  }
  if (nextHash === existing.password_hash) {
    return res.status(400).json({ error: "A nova senha precisa ser diferente da senha atual." });
  }
  await run(
    "UPDATE users SET password_hash = ?, must_change_password = 0, updated_at = datetime('now') WHERE id = ?",
    [nextHash, userId]
  );
  await recordAuditEvent({
    req,
    module: "auth",
    action: "user_password_changed",
    entityType: "user",
    entityId: String(userId),
    result: "success",
    message: "Senha alterada pelo usuario",
    includeBody: false
  });
  const user = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  res.json({ success: true, user: serializeAuthUser(user) });
}

async function handleAuthForceChangePassword(req, res) {
  const userId = Number(req.user?.id || 0);
  const newPassword = String(req.body?.newPassword || "");
  if (!userId) {
    return res.status(401).json({ error: "Sessao expirada. Faca login novamente." });
  }
  const passwordValidation = validatePasswordStrength(newPassword);
  if (!passwordValidation.ok) {
    return res.status(400).json({ error: passwordValidation.error });
  }
  const existing = await get("SELECT id, password_hash, must_change_password FROM users WHERE id = ? LIMIT 1", [userId]);
  if (!existing) {
    return res.status(404).json({ error: "Usuario nao encontrado." });
  }
  if (!Number(existing.must_change_password || 0)) {
    return res.status(400).json({ error: "Troca obrigatoria de senha nao esta pendente para este usuario." });
  }
  const nextHash = hashPassword(newPassword);
  if (nextHash === existing.password_hash) {
    return res.status(400).json({ error: "A nova senha precisa ser diferente da senha temporaria." });
  }
  await run(
    "UPDATE users SET password_hash = ?, must_change_password = 0, updated_at = datetime('now') WHERE id = ?",
    [nextHash, userId]
  );
  await recordAuditEvent({
    req,
    module: "auth",
    action: "user_password_changed",
    entityType: "user",
    entityId: String(userId),
    result: "success",
    message: "Troca obrigatoria de senha concluida",
    includeBody: false,
    metadata: { forced: true }
  });
  const user = await get("SELECT * FROM users WHERE id = ? LIMIT 1", [userId]);
  res.json({ success: true, user: serializeAuthUser(user) });
}

