app.get("/api/ia/vitrine-import/history", requireManager, async (req, res) => {
  try {
    await run(
      `UPDATE ai_vitrine_imports
       SET status = 'processamento_incompleto'
       WHERE status = 'processando'
         AND datetime(created_at) <= datetime('now', '-120 seconds')
         AND COALESCE(created_count, 0) = 0
         AND COALESCE(updated_count, 0) = 0
         AND COALESCE(skipped_count, 0) = 0
         AND COALESCE(error_count, 0) = 0`
    );
    const rows = await all(
      `SELECT * FROM ai_vitrine_imports ORDER BY id DESC LIMIT 20`
    );
    res.json({
      imports: rows.map((row) => ({
        id: Number(row.id || 0),
        filename: row.filename || "",
        original_filename: row.original_filename || "",
        import_type: row.import_type || "tiny",
        status: row.status || "",
        total_rows: Number(row.total_rows || 0),
        valid_rows: Number(row.valid_rows || 0),
        selected_count: Number(row.selected_count || 0),
        created_count: Number(row.created_count || 0),
        updated_count: Number(row.updated_count || 0),
        skipped_count: Number(row.skipped_count || 0),
        error_count: Number(row.error_count || 0),
        summary: safeJsonParse(row.summary_json || "{}", {}),
        created_by: row.created_by || "",
        created_at: row.created_at || ""
      }))
    });
  } catch (error) {
    console.error("Erro ao listar histórico da importação Tiny:", error);
    res.status(500).json({ error: "Falha ao carregar o histórico da importação Tiny." });
  }
});

app.get("/api/pdv/inventory/import/tiny/uploads", requireAnyPermission(["can_manage_products"], "Seu perfil nao pode consultar importacoes Tiny."), async (req, res) => {
  try {
    const limit = Math.min(200, Math.max(20, Number(req.query.limit || 80)));
    const files = [
      ...listTinyImportDirectoryFiles(tinyVitrineImportIncomingDir, "incoming"),
      ...listTinyImportDirectoryFiles(tinyVitrineImportProcessedDir, "processed"),
      ...listTinyImportDirectoryFiles(tinyVitrineImportErrorsDir, "error")
    ].sort((left, right) => new Date(right.uploaded_at).getTime() - new Date(left.uploaded_at).getTime());
    const rows = await all(
      `SELECT created_at, action, result, entity_id, store_name, metadata_json
         FROM audit_logs
        WHERE module = ?
          AND action IN (?, ?)
        ORDER BY datetime(created_at) DESC, id DESC
        LIMIT ?`,
      ["pdv_inventory", "tiny_import_preview_generated", "tiny_import_applied", limit]
    );
    const history = rows.map((row) => {
      const metadata = parseAuditMetadataJson(row.metadata_json || "");
      return {
        created_at: row.created_at,
        action: row.action,
        result: row.result || "",
        preview_id: row.entity_id || "",
        store_name: row.store_name || "",
        filename: metadata.filename || "",
        filenames: Array.isArray(metadata.filenames) ? metadata.filenames : [metadata.filename].filter(Boolean),
        total_rows: Number(metadata.total_rows || 0),
        valid_rows: Number(metadata.valid_rows || 0),
        imported: Number(metadata.imported || 0),
        errors: Number(metadata.errors || 0),
        duplicates: Number(metadata.duplicates || 0),
        negative_stock_rows: Number(metadata.negative_stock_rows || 0),
        import_batch_id: metadata.import_batch_id || row.entity_id || "",
        import_mode: metadata.import_mode || ""
      };
    });
    res.json({
      success: true,
      files: files.slice(0, limit),
      summary: {
        incoming: files.filter((item) => item.status === "incoming").length,
        processed: files.filter((item) => item.status === "processed").length,
        error: files.filter((item) => item.status === "error").length,
        total: files.length
      },
      history
    });
  } catch (error) {
    console.error("Erro ao listar uploads Tiny/Olist:", error);
    res.status(500).json({ error: "Nao foi possivel listar as planilhas enviadas." });
  }
});

app.post("/api/pdv/inventory/import/tiny/preview", requireAnyPermission(["can_manage_products"], "Seu perfil nao pode importar produtos ou estoque."), tinyImportUpload.fields([{ name: "file", maxCount: 20 }, { name: "files", maxCount: 20 }]), async (req, res) => {
  const uploadedFiles = [
    ...(req.files?.file || []),
    ...(req.files?.files || [])
  ];
  if (!uploadedFiles.length) {
    return res.status(400).json({ error: "Formato não suportado. Envie uma planilha .xlsx, .xls ou .csv exportada do Tiny." });
  }

  try {
    cleanupPdvTinyProductImportPreviews();
    const storeAccess = await assertPdvTinyImportStoreAccess(req, req.body?.storeOverride || req.body?.store_id || req.body?.storeId || "");
    if (!storeAccess.ok) {
      uploadedFiles.forEach((file) => {
        if (file?.path && fs.existsSync(file.path)) {
          moveTinyImportFile(file.path, tinyVitrineImportErrorsDir);
        }
      });
      return res.status(storeAccess.status || 400).json({ error: storeAccess.error, store_id: storeAccess.storeId || "" });
    }
    const manualStoreOverride = storeAccess.storeId;
    const requestedImportMode = normalizeLookup(req.body?.importMode || req.body?.import_mode || "");
    const importMode = requestedImportMode === "products_only" || requestedImportMode === "stock_only"
      ? requestedImportMode
      : "products_stock";
    const previewId = crypto.randomUUID();
    const parsedFiles = uploadedFiles.map((file) => {
      const parsed = readTinyVitrineWorkbookFromFile(file.path);
      const mapping = parseTinyPdvImportMapping(req.body?.mapping || "", parsed.headerAnalysis || {});
      const sourceFileName = sanitizeFilename(file.originalname || file.filename || "");
      const mappedRows = applyTinyPdvImportMapping(parsed.rows || [], mapping)
        .map((row) => ({ ...row, __source_file: sourceFileName }));
      return {
        file,
        parsed,
        mapping,
        sourceFileName,
        groupedItems: groupTinyVitrineImportRows(mappedRows, {
          sourceType: parsed.sourceType || "spreadsheet",
          groupByParent: false
        })
      };
    });
    const groupedItems = parsedFiles.flatMap((entry) => entry.groupedItems || []);
    const parsed = parsedFiles[0]?.parsed || {};
    const mapping = parsedFiles[0]?.mapping || {};
    const previewPayload = previewTinyInventoryImport(groupedItems, {
      manualStoreOverride,
      importBatchId: previewId,
      importedBy: req.user?.name || req.user?.email || "",
      importMode
    });
    pdvTinyProductImportPreviews.set(previewId, {
      createdAt: Date.now(),
      createdBy: req.user?.id || 0,
      filePath: uploadedFiles[0]?.path || "",
      filePaths: uploadedFiles.map((file) => file.path).filter(Boolean),
      filename: uploadedFiles[0]?.filename || "",
      filenames: uploadedFiles.map((file) => file.filename || "").filter(Boolean),
      originalFilename: parsedFiles[0]?.sourceFileName || "",
      originalFilenames: parsedFiles.map((entry) => entry.sourceFileName).filter(Boolean),
      worksheetName: parsed.worksheetName,
      sourceType: parsed.sourceType || "spreadsheet",
      delimiter: parsed.delimiter || "",
      groupedItems,
      manualStoreOverride,
      importMode,
      storeId: storeAccess.storeId,
      storeLabel: storeAccess.storeLabel,
      mapping,
      previewRows: previewPayload.preview || [],
      summary: previewPayload.summary
    });

    await recordAuditEvent({
      req,
      module: "pdv_inventory",
      action: "tiny_import_preview_generated",
      entityType: "pdv_tiny_import_preview",
      entityId: previewId,
      storeId: storeAccess.storeId,
      storeName: storeAccess.storeLabel,
      result: "success",
      includeBody: false,
      metadata: {
        filename: parsedFiles[0]?.sourceFileName || "",
        filenames: parsedFiles.map((entry) => entry.sourceFileName).filter(Boolean),
        source_type: parsed.sourceType || "spreadsheet",
        total_rows: Number(previewPayload.summary?.totalRows || 0),
        valid_rows: Number(previewPayload.summary?.validRows || 0),
        negative_stock_rows: Number(previewPayload.summary?.productsWithNegativeStock || 0),
        import_mode: importMode,
        products_bound_to_store: Number(previewPayload.summary?.productsBoundToAppliedStore || 0)
      }
    });

    res.json({
      success: true,
      previewId,
      worksheetName: parsed.worksheetName,
      sourceType: parsed.sourceType || "spreadsheet",
      delimiter: parsed.delimiter || "",
      headersOriginais: parsed.headerAnalysis?.originalHeaders || [],
      headersNormalizados: parsed.headerAnalysis?.normalizedHeaders || [],
      availableHeaders: parsed.headerAnalysis?.originalHeaders || [],
      mapping,
      fields: PDV_TINY_IMPORT_FIELD_DEFINITIONS,
      summary: previewPayload.summary,
      preview: (previewPayload.preview || []).slice(0, 300),
      storeOverride: manualStoreOverride,
      importMode,
      store_id: storeAccess.storeId,
      store_label: storeAccess.storeLabel,
      files: parsedFiles.map((entry) => entry.sourceFileName).filter(Boolean),
      diagnostics: {
        selectedSheet: parsed.worksheetName || "",
        missingMinimum: parsed.headerAnalysis?.missingMinimum || []
      }
    });
  } catch (error) {
    uploadedFiles.forEach((file) => {
      if (file?.path && fs.existsSync(file.path)) {
        moveTinyImportFile(file.path, tinyVitrineImportErrorsDir);
      }
    });
    console.error("Erro ao gerar preview Tiny do PDV:", error);
    res.status(400).json({
      error: error.message || "Não foi possível importar a planilha. Verifique o arquivo e tente novamente.",
      ...(error.details || {})
    });
  }
});

app.post("/api/pdv/inventory/import/tiny/commit", requireAnyPermission(["can_manage_products"], "Seu perfil nao pode importar produtos ou estoque."), async (req, res) => {
  let filePath = "";
  let filePaths = [];
  try {
    cleanupPdvTinyProductImportPreviews();
    const previewId = String(req.body?.previewId || "").trim();
    if (!previewId) {
      return res.status(400).json({ error: "Gere a prévia da importação Tiny antes de confirmar." });
    }
    const preview = pdvTinyProductImportPreviews.get(previewId);
    if (!preview) {
      return res.status(404).json({ error: "Preview da importação Tiny não encontrado ou expirado." });
    }
    const storeAccess = await assertPdvTinyImportStoreAccess(req, preview.manualStoreOverride || preview.storeId || "");
    if (!storeAccess.ok) {
      return res.status(storeAccess.status || 400).json({ error: storeAccess.error, store_id: storeAccess.storeId || "" });
    }
    filePath = preview.filePath;
    filePaths = Array.isArray(preview.filePaths) && preview.filePaths.length ? preview.filePaths : [filePath].filter(Boolean);
    const payload = await commitTinyInventoryImport(preview.groupedItems || [], req.user || {}, {
      manualStoreOverride: storeAccess.storeId,
      importBatchId: previewId,
      importedBy: req.user?.name || req.user?.email || "",
      importMode: preview.importMode || "",
      previewRows: preview.previewRows || [],
      previewSummary: preview.summary || null
    });
    filePaths.forEach((targetPath) => {
      if (targetPath && fs.existsSync(targetPath)) {
        moveTinyImportFile(targetPath, payload.errors ? tinyVitrineImportErrorsDir : tinyVitrineImportProcessedDir);
      }
    });
    pdvTinyProductImportPreviews.delete(previewId);
    await recordAuditEvent({
      req,
      module: "pdv_inventory",
      action: "tiny_import_applied",
      entityType: "pdv_tiny_import_preview",
      entityId: previewId,
      storeId: storeAccess.storeId,
      storeName: storeAccess.storeLabel,
      result: payload.errors ? "failed" : "success",
      includeBody: false,
      metadata: {
        filename: preview.originalFilename || preview.filename || "",
        filenames: preview.originalFilenames || [],
        source_type: preview.sourceType || "",
        import_batch_id: previewId,
        total_rows: Number(payload.totalRows || 0),
        imported: Number(payload.imported || 0),
        pending: Number(payload.pending || 0),
        negative_stock_rows: Number(payload.previewSummary?.productsWithNegativeStock || 0),
        import_mode: preview.importMode || payload.previewSummary?.importMode || "",
        duplicates: Number(payload.duplicates || 0),
        errors: Number(payload.errors || 0)
      }
    });
    res.json({
      success: true,
      summary: {
        totalRows: Number(payload.totalRows || 0),
        imported: Number(payload.imported || 0),
        pending: Number(payload.pending || 0),
        duplicates: Number(payload.duplicates || 0),
        ignored: Number(payload.ignored || 0),
        errors: Number(payload.errors || 0)
      },
      previewSummary: payload.previewSummary || null,
      importedProducts: payload.importedProducts || [],
      ignoredRows: payload.ignoredRows || [],
      errorRows: payload.errorRows || []
    });
  } catch (error) {
    filePaths.forEach((targetPath) => {
      if (targetPath && fs.existsSync(targetPath)) {
        moveTinyImportFile(targetPath, tinyVitrineImportErrorsDir);
      }
    });
    console.error("Erro ao concluir importação Tiny do PDV:", error);
    res.status(500).json({
      error: error.message || "Não foi possível importar a planilha. Verifique o arquivo e tente novamente."
    });
  }
});

